/**
 * Hands the catalog sync off to the upstream ERP/PIM pipeline.
 *
 * This only *triggers* the job — it does not walk the SKUs inline. A real sync
 * touches thousands of records, so the admin request must not wait for it; the
 * job runs on its own and the tag invalidation below lets readers pick up the
 * new data as it lands.
 */
export async function requestCatalogSync(): Promise<void> {
  // Simulate enqueueing the job (publish to a queue / POST to the ERP webhook).
  await new Promise((resolve) => setTimeout(resolve, 50))
}

